from contextlib import asynccontextmanager
from typing import List, Optional

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field, field_validator
from sqlmodel import Field as SQLField, Session, SQLModel, create_engine, select

engine = create_engine("sqlite:///bakery.db", connect_args={"check_same_thread": False})


class Cake(SQLModel, table=True):
    id: Optional[int] = SQLField(default=None, primary_key=True)
    name: str
    price: float


class Order(SQLModel, table=True):
    id: Optional[int] = SQLField(default=None, primary_key=True)
    cake_id: int = SQLField(foreign_key="cake.id")
    customer_name: str


class CakeIn(BaseModel):
    name: str = Field(strict=True)
    price: float = Field(strict=True, ge=0, allow_inf_nan=False)

    @field_validator("name")
    @classmethod
    def name_not_empty(cls, v: str) -> str:
        v = v.strip()
        if not v:
            raise ValueError("name must not be empty")
        return v


class OrderIn(BaseModel):
    cake_id: int = Field(strict=True)
    customer_name: str = Field(strict=True)

    @field_validator("customer_name")
    @classmethod
    def customer_not_empty(cls, v: str) -> str:
        v = v.strip()
        if not v:
            raise ValueError("customer_name must not be empty")
        return v


@asynccontextmanager
async def lifespan(app: FastAPI):
    SQLModel.metadata.create_all(engine)
    yield


app = FastAPI(title="Bakery", lifespan=lifespan)


@app.post("/cakes", response_model=Cake, status_code=201)
def add_cake(data: CakeIn):
    with Session(engine) as s:
        cake = Cake(name=data.name, price=data.price)
        s.add(cake)
        s.commit()
        s.refresh(cake)
        return cake


@app.get("/cakes", response_model=List[Cake])
def list_cakes():
    with Session(engine) as s:
        return s.exec(select(Cake).order_by(Cake.id)).all()


@app.post("/orders", response_model=Order, status_code=201)
def add_order(data: OrderIn):
    with Session(engine) as s:
        if s.get(Cake, data.cake_id) is None:
            raise HTTPException(status_code=404, detail="Cake not found")
        order = Order(cake_id=data.cake_id, customer_name=data.customer_name)
        s.add(order)
        s.commit()
        s.refresh(order)
        return order

